import org.junit.jupiter.api.*;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.order.service.OrderValues.*;

class OrderShipmentDispatchServiceTest {
    OrderShipmentServiceTest fixture;OrderShipmentDispatchService dispatch;OrderShipmentWmsClient wms;OrderWarehouseClient inventory;long shipment;
    @BeforeAll static void setup(){OrderShipmentServiceTest.setup();}
    Map<String,Object> row(Object...pairs){return fixture.row(pairs);}
    @BeforeEach void seed(){
        fixture=new OrderShipmentServiceTest();fixture.seed();wms=mock(OrderShipmentWmsClient.class);inventory=mock(OrderWarehouseClient.class);dispatch=new OrderShipmentDispatchService();ReflectionTestUtils.setField(dispatch,"repository",fixture.repository);ReflectionTestUtils.setField(dispatch,"wms",wms);ReflectionTestUtils.setField(dispatch,"inventory",inventory);
        fixture.db.update("UPDATE oms_platform_order SET platform_created='2026-10-10 10:00:00',processing_payload=?",encode(row("trade_fullinfo_get_response",row("trade",row("receiver_state","北京市","receiver_city","北京市","receiver_district","海淀区","receiver_address","测试地址")))));fixture.db.update("UPDATE oms_order SET review_at=NOW()");
        when(wms.resolve(anyString(),anyMap(),anyString())).thenReturn(R.ok(route()));when(wms.submit(anyString(),anyMap(),anyString())).thenAnswer(i->R.ok(reply("ACCEPTED")));when(wms.query(anyString(),anyMap(),anyString())).thenAnswer(i->R.ok(reply("ACCEPTED")));
    }
    @AfterEach void clear(){fixture.db.update("DELETE FROM oms_order_shipment_dispatch");}
    Map<String,Object> route(){return row("connection_id",7,"connection_name","fixture","provider","QIMEN","api_version","2.0","environment","TEST","external_warehouse","EXT-W","external_owner","EXT-O");}
    long create(long qty){Map<String,Object> receipt=fixture.receipt(1,qty,"V1","R1");receipt.put("batch_code","B001");fixture.mirror(Arrays.asList(receipt));shipment=number(fixture.generate(0).get(0),"id");fixture.db.update("UPDATE oms_order_shipment SET status='WAIT_DISPATCH',carrier_code='SF',carrier_name='express',warehouse_carrier_code='SF',carrier_match_status='MATCHED',receiver_province='北京'");when(inventory.receipts(anyString(),anyLong(),anyString(),anyString())).thenReturn(R.ok(Arrays.asList(receipt)));return shipment;}
    Map<String,Object> document(){return fixture.db.query("SELECT * FROM oms_order_shipment WHERE id=?",ROW,shipment).get(0);}
    Map<String,Object> intent(){return fixture.db.query("SELECT * FROM oms_order_shipment_dispatch WHERE shipment_id=?",ROW,shipment).get(0);}
    Map<String,Object> reply(String state){Map<String,Object> task=intent();return row("id",77,"shipment_id",shipment,"shipment_sn",task.get("shipment_sn"),"payload_hash",task.get("payload_hash"),"dispatch_state",state,"external_order","ACCEPTED".equals(state)?"WMS-77":"","warehouse_status","ACCEPTED".equals(state)?"ACCEPT":"","last_error","FAILED".equals(state)?"warehouse rejected":"","query_message","");}
    Map<String,Object> request(long version){return row("items",Arrays.asList(row("id",shipment,"control_version",version)));}
    Map<String,Object> submit(long version){return dispatch.submit("VERIFY",request(version),"operator").get(0);}
    void due(){fixture.db.update("UPDATE oms_order_shipment_dispatch SET next_attempt=NOW(),lease_until=NULL");}
    long count(){return fixture.db.queryForObject("SELECT COUNT(*) FROM oms_order_shipment_dispatch",Long.class);}
    @SuppressWarnings("unchecked") @Test void mixedPurchasedAndGiftLinesUseOneBatchedSourceReadAndOneWarehouseIntent(){
        List<Map<String,Object>> receipts=new ArrayList<>();Map<String,Object> paid=fixture.receipt(1,10,"V1","R1");paid.put("batch_code","B001");receipts.add(paid);
        for(int i=1;i<=2;i++){String reference="GIFT:77:"+i;fixture.db.update("INSERT INTO oms_order_line(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,reserved_quantity,payment,gift_plan_id,stock_reference) VALUES ('VERIFY',?,'','A','gift',1,1,0,77,?)",fixture.id,reference);Map<String,Object> gift=fixture.receipt(1+i,1,"V1","R1");gift.put("platform_tid",reference);gift.put("platform_oid","");gift.put("batch_code","B001");receipts.add(gift);}
        fixture.mirror(receipts);shipment=number(fixture.generate(0).get(0),"id");fixture.db.update("UPDATE oms_order_shipment SET status='WAIT_DISPATCH',carrier_code='SF',carrier_name='express',warehouse_carrier_code='SF',carrier_match_status='MATCHED'");
        when(inventory.receiptsBatch(anyString(),anyMap(),anyString())).thenAnswer(call->{Map<String,Object> command=call.getArgument(1);assertEquals(new TreeSet<>(Arrays.asList("12345","GIFT:77:1","GIFT:77:2")),new TreeSet<>((Collection<String>)command.get("references")));return R.ok(receipts);});
        Map<String,Object> preview=dispatch.preview("VERIFY",request(1)).get(0);assertEquals(true,preview.get("success"),preview.toString());List<Map<String,Object>> lines=(List<Map<String,Object>>)preview.get("lines");assertEquals(3,lines.size());assertEquals(3,lines.stream().map(l->text(l,"stock_reference")).distinct().count());assertEquals(2,lines.stream().filter(l->l.get("gift_plan_id")!=null&&text(l,"platform_oid").isEmpty()).count());verify(inventory,times(1)).receiptsBatch(anyString(),anyMap(),anyString());verify(inventory,never()).receipts(anyString(),anyLong(),anyString(),anyString());
        assertEquals(true,submit(1).get("success"));assertEquals(1,count());assertEquals(1,fixture.db.queryForObject("SELECT COUNT(*) FROM oms_order_shipment",Integer.class));
    }
    @Test void previewShowsOnlyCurrentShipmentQuantityAndDoesNotCreateWarehouseIntent(){
        create(6);fixture.db.update("UPDATE oms_platform_order SET processing_payload=?",encode(row("trade_fullinfo_get_response",row("trade",row("receiver_state","北京市","receiver_address","测试地址","orders",row("order",Arrays.asList(row("oid","123450","sku_properties_name","颜色:蓝;尺码:M"))))))));
        Map<String,Object> preview=dispatch.preview("VERIFY",request(1)).get(0);assertEquals(true,preview.get("success"));assertEquals(6,number(preview,"quantity"));assertEquals("CURRENT",preview.get("snapshot_scope"));
        List<Map<String,Object>> lines=(List<Map<String,Object>>)preview.get("lines");assertEquals(1,lines.size());assertEquals(6,number(lines.get(0),"quantity"));assertEquals("B001",lines.get(0).get("batch_code"));assertEquals("颜色:蓝;尺码:M",lines.get(0).get("spec"));
        assertEquals(10,fixture.db.queryForObject("SELECT quantity FROM oms_order_line",Integer.class));assertEquals(0,count());assertFalse(preview.containsKey("receiver"));verify(wms,never()).submit(anyString(),anyMap(),anyString());
    }
    @Test void previewPreservesSeparateBatchLinesWithinOneVirtualWarehouse(){
        Map<String,Object> a=fixture.receipt(1,2,"V1","R1"),b=fixture.receipt(2,4,"V1","R1");a.put("batch_code","B001");b.put("batch_code","B002");fixture.mirror(Arrays.asList(a,b));shipment=number(fixture.generate(0).get(0),"id");
        fixture.db.update("UPDATE oms_order_shipment SET status='WAIT_DISPATCH',carrier_code='SF',carrier_name='express',warehouse_carrier_code='SF',carrier_match_status='MATCHED'");when(inventory.receipts(anyString(),anyLong(),anyString(),anyString())).thenReturn(R.ok(Arrays.asList(a,b)));
        Map<String,Object> preview=dispatch.preview("VERIFY",request(1)).get(0);assertEquals(true,preview.get("success"));List<Map<String,Object>> lines=(List<Map<String,Object>>)preview.get("lines");assertEquals(2,lines.size());assertEquals(6,lines.stream().mapToLong(l->number(l,"quantity")).sum());assertEquals("B001",lines.get(0).get("batch_code"));assertEquals("B002",lines.get(1).get("batch_code"));assertEquals(0,count());
    }
    @Test void samePhysicalWarehouseVirtualDocumentsDispatchSeparatelyWithIndependentResults(){
        Map<String,Object> a=fixture.receipt(1,6,"V1","R1"),b=fixture.receipt(2,4,"V2","R1");a.put("batch_code","B001");b.put("batch_code","B002");
        fixture.mirror(Arrays.asList(a,b));List<Map<String,Object>> documents=fixture.generate(0);assertEquals(2,documents.size());
        fixture.db.update("UPDATE oms_order_shipment SET status='WAIT_DISPATCH',carrier_code='SF',carrier_name='express',warehouse_carrier_code='SF',carrier_match_status='MATCHED'");
        when(inventory.receipts(anyString(),anyLong(),anyString(),anyString())).thenReturn(R.ok(Arrays.asList(a,b)));
        for(int index=0;index<documents.size();index++){
            shipment=number(documents.get(index),"id");Map<String,Object> preview=dispatch.preview("VERIFY",request(1)).get(0);
            assertEquals(true,preview.get("success"));assertEquals(index==0?6:4,number(preview,"quantity"));
            List<Map<String,Object>> lines=(List<Map<String,Object>>)preview.get("lines");assertEquals(1,lines.size());assertEquals(index==0?"V1":"V2",lines.get(0).get("store_code"));
            assertEquals(true,submit(1).get("success"));final boolean accept=index==0;
            when(wms.submit(anyString(),anyMap(),anyString())).thenAnswer(i->R.ok(reply(accept?"ACCEPTED":"FAILED")));
            dispatch.process("VERIFY",shipment);assertEquals(accept?"ACCEPTED":"FAILED",intent().get("state"));
        }
        assertEquals(2,count());verify(wms,times(2)).submit(anyString(),anyMap(),anyString());
        assertEquals(1,fixture.db.queryForObject("SELECT COUNT(*) FROM oms_order_shipment_dispatch WHERE state='ACCEPTED'",Integer.class));
        assertEquals(1,fixture.db.queryForObject("SELECT COUNT(*) FROM oms_order_shipment_dispatch WHERE state='FAILED'",Integer.class));
        assertEquals(0,fixture.db.queryForObject("SELECT COUNT(*) FROM oms_order_shipment_package",Integer.class));
        assertEquals(0,number(fixture.summary(),"shipped_quantity"));assertEquals(10,fixture.db.queryForObject("SELECT reserved_quantity FROM oms_order_line",Integer.class));
    }
    @Test void blockedPreviewKeepsOwnedProductInformationAndNeverLeaksAnotherCompany(){
        create(6);fixture.db.update("UPDATE oms_order SET manual_hold=1");Map<String,Object> blocked=dispatch.preview("VERIFY",request(1)).get(0);assertEquals(false,blocked.get("success"));assertTrue(text(blocked,"message").contains("挂起"));assertEquals(1,((List<?>)blocked.get("lines")).size());
        Map<String,Object> other=dispatch.preview("OTHER",request(1)).get(0);assertEquals(false,other.get("success"));assertFalse(other.containsKey("lines"));assertFalse(other.containsKey("shipment_sn"));assertEquals(0,count());verifyNoInteractions(inventory,wms);
    }
    @Test void retryPreviewAndDetailUseFrozenProductSnapshotAndListFiltersDispatchState(){
        create(6);submit(1);when(wms.submit(anyString(),anyMap(),anyString())).thenAnswer(i->R.ok(reply("FAILED")));dispatch.process("VERIFY",shipment);
        String frozen=text(intent(),"payload_json");fixture.db.update("UPDATE oms_order_shipment_line SET goods_name='new display name'");Map<String,Object> preview=dispatch.preview("VERIFY",request(number(document(),"control_version"))).get(0);
        assertEquals(true,preview.get("success"));assertEquals("FROZEN",preview.get("snapshot_scope"));assertEquals(6,number(preview,"quantity"));assertEquals("goods",((List<Map<String,Object>>)preview.get("lines")).get(0).get("goods_name"));assertEquals(frozen,intent().get("payload_json"));
        Map<String,Object> detail=fixture.service.detail("VERIFY",shipment);assertEquals("goods",((List<Map<String,Object>>)detail.get("dispatch_lines")).get(0).get("goods_name"));assertEquals(6,number(detail,"dispatch_quantity"));
        assertEquals(1,fixture.service.list("VERIFY","",null,"","","","FAILED",1,20).getTotal());assertEquals(0,fixture.service.list("VERIFY","",null,"","","","UNKNOWN",1,20).getTotal());assertEquals(0,fixture.service.list("OTHER","",null,"","","","FAILED",1,20).getTotal());assertThrows(IllegalArgumentException.class,()->fixture.service.list("VERIFY","",null,"","","","INVALID",1,20));
    }
    @Test void queuedIntentFreezesCarrierAndAcceptanceChangesOnlyRoutingProgress(){create(10);Map<String,Object> quantities=fixture.db.query("SELECT quantity,reserved_quantity FROM oms_order_line",ROW).get(0);assertEquals(true,submit(1).get("success"));assertEquals("DISPATCHING",document().get("status"));assertEquals("PENDING",intent().get("state"));assertEquals(false,fixture.service.detail("VERIFY",shipment).get("can_match_carrier"));assertEquals(true,fixture.summary().get("can_void"));assertEquals("DISPATCHING",fixture.summary().get("business_status"));dispatch.process("VERIFY",shipment);assertEquals("ACCEPTED",intent().get("state"));assertEquals("WAREHOUSE_PROCESSING",document().get("status"));assertEquals("WAREHOUSE_PROCESSING",fixture.summary().get("business_status"));assertEquals(10,number(fixture.summary(),"warehouse_accepted_quantity"));assertEquals(quantities,fixture.db.query("SELECT quantity,reserved_quantity FROM oms_order_line",ROW).get(0));assertEquals(0,number(fixture.summary(),"shipped_quantity"));assertFalse(fixture.service.detail("VERIFY",shipment).containsKey("payload_json"));assertEquals(false,submit(number(document(),"control_version")).get("success"));verify(wms,times(1)).submit(anyString(),anyMap(),anyString());}
    @Test void lostReplyIsQueriedAndNeverBlindlySubmittedAgain(){create(6);assertEquals(true,submit(1).get("success"));when(wms.submit(anyString(),anyMap(),anyString())).thenThrow(new IllegalStateException("timeout"));dispatch.process("VERIFY",shipment);assertEquals("UNKNOWN",intent().get("state"));assertEquals("DISPATCHING",document().get("status"));assertEquals(false,submit(2).get("success"));due();dispatch.process("VERIFY",shipment);assertEquals("ACCEPTED",intent().get("state"));verify(wms,times(1)).submit(anyString(),anyMap(),anyString());verify(wms,times(1)).query(anyString(),anyMap(),anyString());}
    @Test void definitiveFailureCanRetryTheSameSnapshotWithNewVersion(){create(6);submit(1);when(wms.submit(anyString(),anyMap(),anyString())).thenAnswer(i->R.ok(reply("FAILED")));dispatch.process("VERIFY",shipment);String json=text(intent(),"payload_json");assertEquals("FAILED",intent().get("state"));assertEquals("WAIT_DISPATCH",document().get("status"));assertEquals(false,fixture.service.detail("VERIFY",shipment).get("can_match_carrier"));assertEquals(true,fixture.service.detail("VERIFY",shipment).get("can_dispatch"));assertEquals(true,submit(3).get("success"));when(wms.submit(anyString(),anyMap(),anyString())).thenAnswer(i->{assertEquals(true,((Map<?,?>)i.getArgument(1)).get("retry"));return R.ok(reply("ACCEPTED"));});dispatch.process("VERIFY",shipment);assertEquals(json,intent().get("payload_json"));assertEquals(1,count());verify(wms,times(2)).submit(anyString(),anyMap(),anyString());}
    @Test void sourceAndWarehouseConfigurationGuardsNeverCreateIntent(){create(6);fixture.db.update("UPDATE oms_order SET manual_hold=1");assertEquals(false,submit(1).get("success"));fixture.db.update("UPDATE oms_order SET manual_hold=0");fixture.db.update("UPDATE oms_platform_order SET change_pending=1");assertEquals(false,submit(1).get("success"));fixture.db.update("UPDATE oms_platform_order SET change_pending=0");when(wms.resolve(anyString(),anyMap(),anyString())).thenReturn(R.fail("虚仓为自动虚拟出库"));assertTrue(text(dispatch.preview("VERIFY",request(1)).get(0),"message").contains("自动虚拟"));assertEquals(false,submit(1).get("success"));assertEquals(0,count());verify(wms,never()).submit(anyString(),anyMap(),anyString());}
    @Test void queuedHoldStopsCreateUntilReleased(){create(6);submit(1);fixture.db.update("UPDATE oms_order SET manual_hold=1");dispatch.process("VERIFY",shipment);assertEquals("PENDING",intent().get("state"));assertTrue(text(intent(),"last_error").contains("挂起"));verify(wms,never()).submit(anyString(),anyMap(),anyString());fixture.db.update("UPDATE oms_order SET manual_hold=0");due();dispatch.process("VERIFY",shipment);assertEquals("ACCEPTED",intent().get("state"));}
    @Test void wrongReceiptAndTenantCannotSubmit(){create(6);Map<String,Object> wrong=fixture.receipt(1,5,"V1","R1");wrong.put("batch_code","B001");when(inventory.receipts(anyString(),anyLong(),anyString(),anyString())).thenReturn(R.ok(Arrays.asList(wrong)));assertEquals(false,submit(1).get("success"));assertEquals(false,dispatch.submit("OTHER",request(1),"test").get(0).get("success"));assertEquals(0,count());verify(wms,never()).resolve(anyString(),anyMap(),anyString());}
    @Test void concurrentSubmissionHasOneIntentAndOneWinner() throws Exception {create(6);ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{List<Future<Boolean>> jobs=new ArrayList<>();for(int i=0;i<2;i++)jobs.add(pool.submit(()->{start.await();return Boolean.TRUE.equals(submit(1).get("success"));}));start.countDown();int winners=0;for(Future<Boolean> job:jobs)if(job.get(10,TimeUnit.SECONDS))winners++;assertEquals(1,winners);}finally{pool.shutdownNow();}assertEquals(1,count());assertEquals(2,number(document(),"control_version"));}
    @Test void unknownNotFoundDoesNotReleaseStockAndAcceptedQueryDoesNotPostShipmentQuantity(){create(6);submit(1);when(wms.submit(anyString(),anyMap(),anyString())).thenThrow(new IllegalStateException());dispatch.process("VERIFY",shipment);when(wms.query(anyString(),anyMap(),anyString())).thenAnswer(i->{Map<String,Object> reply=reply("UNKNOWN");reply.put("query_message","仓库查无单据，请核对");return R.ok(reply);});dispatch.query("VERIFY",shipment,"operator");assertEquals("UNKNOWN",intent().get("state"));assertEquals(false,submit(2).get("success"));assertEquals(10,fixture.db.queryForObject("SELECT reserved_quantity FROM oms_order_line",Integer.class));when(wms.query(anyString(),anyMap(),anyString())).thenAnswer(i->{Map<String,Object> reply=reply("ACCEPTED");reply.put("warehouse_status","DELIVERED");reply.put("query_message","等待完整出库明细回传");return R.ok(reply);});dispatch.query("VERIFY",shipment,"operator");assertEquals(0,number(fixture.summary(),"shipped_quantity"));assertEquals("WAREHOUSE_PROCESSING",document().get("status"));}
    @Test void queuedVoidIsBlockedAndDefinitiveUnacceptedFailureCanStopLocally(){create(6);submit(1);OrderVoidService voids=fixture.voids(mock(OrderStockClient.class));Map<String,Object> body=row("orders",Arrays.asList(row("id",fixture.id,"control_version",2)),"reason","cancel","confirm_local_void",1);assertEquals(false,voids.request("VERIFY",body,"operator").get(0).get("submitted"));when(wms.submit(anyString(),anyMap(),anyString())).thenAnswer(i->R.ok(reply("FAILED")));dispatch.process("VERIFY",shipment);body.put("orders",Arrays.asList(row("id",fixture.id,"control_version",3)));assertEquals(true,voids.request("VERIFY",body,"operator").get(0).get("submitted"));assertEquals("CANCELED",intent().get("state"));assertEquals("VOIDING",document().get("status"));}
    @Test void mismatchedWarehouseAcknowledgementCannotMarkAccepted(){create(6);submit(1);when(wms.submit(anyString(),anyMap(),anyString())).thenAnswer(i->{Map<String,Object> reply=reply("ACCEPTED");reply.put("payload_hash","different");return R.ok(reply);});dispatch.process("VERIFY",shipment);assertEquals("UNKNOWN",intent().get("state"));assertEquals("DISPATCHING",document().get("status"));assertEquals(true,fixture.summary().get("can_void"));}
    @Test void missingBridgeLedgerCannotRequeueAnUnknownWarehouseOutcome(){create(6);submit(1);when(wms.submit(anyString(),anyMap(),anyString())).thenThrow(new IllegalStateException("lost reply"));dispatch.process("VERIFY",shipment);when(wms.query(anyString(),anyMap(),anyString())).thenAnswer(i->R.ok(row("dispatch_state","MISSING")));Map<String,Object> reply=dispatch.query("VERIFY",shipment,"operator");assertEquals("UNKNOWN",reply.get("dispatch_state"));assertTrue(text(reply,"message").contains("不能自动重新下发"));due();dispatch.process("VERIFY",shipment);verify(wms,times(1)).submit(anyString(),anyMap(),anyString());assertEquals("UNKNOWN",intent().get("state"));}
    @Test void postedReceiptReplacesStaleWarehouseQueryMessageAndNeverRepostsInventory(){
        create(6);submit(1);dispatch.process("VERIFY",shipment);
        fixture.db.update("UPDATE oms_order_shipment_line SET shipped_quantity=6 WHERE shipment_id=?",shipment);
        fixture.db.update("UPDATE oms_order_shipment SET status='SHIPPED' WHERE id=?",shipment);
        fixture.db.update("UPDATE oms_order_shipment_dispatch SET warehouse_status='DELIVERED',query_message='等待完整出库明细回传，实际发货数量尚未更新' WHERE shipment_id=?",shipment);
        Map<String,Object> detail=fixture.service.detail("VERIFY",shipment);
        assertEquals("SHIPPED",detail.get("wms_fulfillment_state"));assertTrue(text(detail,"wms_progress_message").contains("实际出库 6 / 6 件"));assertFalse(text(detail,"wms_progress_message").contains("尚未更新"));
        when(wms.query(anyString(),anyMap(),anyString())).thenAnswer(i->{Map<String,Object> reply=reply("ACCEPTED");reply.put("warehouse_status","DELIVERED");reply.put("query_message","等待完整出库明细回传，实际发货数量尚未更新");return R.ok(reply);});
        Map<String,Object> queried=dispatch.query("VERIFY",shipment,"operator");
        assertTrue(text(queried,"query_message").contains("实际出库 6 / 6 件"));assertEquals(queried.get("query_message"),intent().get("query_message"));assertEquals("SHIPPED",document().get("status"));assertEquals(6,number(fixture.service.detail("VERIFY",shipment),"shipped_quantity"));verify(inventory,never()).warehouseOutbound(anyString(),anyMap(),anyString());
    }
    @Test void partialReceiptIsNotMistakenForFullShipmentWhenWarehouseReportsDelivered(){
        create(6);submit(1);dispatch.process("VERIFY",shipment);
        fixture.db.update("UPDATE oms_order_shipment_line SET shipped_quantity=2 WHERE shipment_id=?",shipment);
        when(wms.query(anyString(),anyMap(),anyString())).thenAnswer(i->{Map<String,Object> reply=reply("ACCEPTED");reply.put("warehouse_status","DELIVERED");reply.put("query_message","等待完整出库明细回传");return R.ok(reply);});
        dispatch.query("VERIFY",shipment,"operator");Map<String,Object> detail=fixture.service.detail("VERIFY",shipment);
        assertEquals("PART_SHIPPED",detail.get("wms_fulfillment_state"));assertEquals("PART_SHIPPED",document().get("status"));assertTrue(text(detail,"wms_progress_message").contains("实际出库 2 / 6 件，剩余 4 件"));assertTrue(text(detail,"wms_progress_message").contains("待补齐包裹"));assertEquals(2,number(detail,"shipped_quantity"));verify(inventory,never()).warehouseOutbound(anyString(),anyMap(),anyString());
    }
}
